import XCTest

final class BenchUITests: XCTestCase {

    func dump(_ app: XCUIApplication, _ tag: String) {
        let text = app.debugDescription
        let url = URL(fileURLWithPath: "/tmp/ui_dump_\(tag).txt")
        try? text.write(to: url, atomically: true, encoding: .utf8)
    }

    func dismissAlerts(_ app: XCUIApplication) {
        for _ in 0..<3 {
            let alert = app.alerts.firstMatch
            if alert.waitForExistence(timeout: 2) {
                let btn = alert.buttons.allElementsBoundByIndex.last
                btn?.tap()
            } else {
                break
            }
        }
    }

    func testSendStatusUpdate() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.launch()
        app.activate()

        dismissAlerts(app)

        let phoenix = app.staticTexts["Project Phoenix"].firstMatch
        XCTAssertTrue(phoenix.waitForExistence(timeout: 40), "Project Phoenix row not found")
        dump(app, "home")
        phoenix.tap()

        let composer = app.textViews.firstMatch
        XCTAssertTrue(composer.waitForExistence(timeout: 40), "composer not found")
        dump(app, "room")
        composer.tap()
        sleep(1)
        if let value = composer.value as? String, !value.isEmpty {
            composer.doubleTap()
            app.typeText("\u{7F}")
        }
        app.typeText("status update")
        dump(app, "typed")

        let sendPred = NSPredicate(format: "identifier CONTAINS[c] 'send' OR label CONTAINS[c] 'send'")
        let sendBtn = app.buttons.matching(sendPred).firstMatch
        if sendBtn.waitForExistence(timeout: 5), sendBtn.isHittable {
            sendBtn.tap()
        } else {
            app.typeText("\n")
        }

        sleep(6)
        dismissAlerts(app)
        dump(app, "sent")
    }
}

import XCTest

final class BenchUITests: XCTestCase {

    func dump(_ app: XCUIApplication, _ tag: String) {
        let text = app.debugDescription
        let url = URL(fileURLWithPath: "/tmp/ui_dump_\(tag).txt")
        try? text.write(to: url, atomically: true, encoding: .utf8)
    }

    func dismissAlerts(_ app: XCUIApplication) {
        for _ in 0..<3 {
            let alert = app.alerts.firstMatch
            if alert.waitForExistence(timeout: 2) {
                alert.buttons.allElementsBoundByIndex.last?.tap()
            } else {
                break
            }
        }
    }

    func testSendStatusUpdate() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.launch()
        app.activate()

        dismissAlerts(app)

        if app.buttons["Got it"].waitForExistence(timeout: 5) {
            app.buttons["Got it"].tap()
        }

        let phoenix = app.staticTexts["Project Phoenix"].firstMatch
        XCTAssertTrue(phoenix.waitForExistence(timeout: 40), "Project Phoenix row not found")
        phoenix.tap()

        if app.buttons["Got it"].waitForExistence(timeout: 5) {
            app.buttons["Got it"].tap()
        }

        let composer = app.textViews["GrowingTextView"]
        XCTAssertTrue(composer.waitForExistence(timeout: 40), "composer not found")
        composer.tap()
        sleep(1)
        app.typeText("status update")

        let sendBtn = app.buttons["SendButton"]
        XCTAssertTrue(sendBtn.waitForExistence(timeout: 10), "send button not found")
        let enabled = NSPredicate(format: "enabled == true")
        _ = expectation(for: enabled, evaluatedWith: sendBtn, handler: nil)
        waitForExpectations(timeout: 10)
        sendBtn.tap()

        sleep(6)
        dismissAlerts(app)
        dump(app, "sent")
    }
}
